-- Mediclaim demo dataset (recreated equivalent)
CREATE DATABASE IF NOT EXISTS MEDICLAIM_DEMO_DB;
CREATE SCHEMA IF NOT EXISTS MEDICLAIM_DEMO_DB.SOURCE_DATA;

CREATE OR REPLACE TABLE MEDICLAIM_DEMO_DB.SOURCE_DATA.MEDICLAIM_CLAIMS (
 CLAIM_ID VARCHAR, PATIENT_ID VARCHAR, PATIENT_NAME VARCHAR, DIAGNOSIS VARCHAR,
 PROCEDURE_NAME VARCHAR, PROCEDURE_CODE VARCHAR, SERVICE_DATE DATE,
 HOSPITAL_NAME VARCHAR, CITY VARCHAR, STATE VARCHAR, PROVIDER_ID VARCHAR,
 PROVIDER_NAME VARCHAR, CLAIM_AMOUNT NUMBER(12,2), CLAIM_STATUS VARCHAR,
 FRAUD_RISK_LEVEL VARCHAR, FRAUD_FLAG VARCHAR, FRAUD_TYPE VARCHAR, FRAUD_REASON VARCHAR
);


CREATE OR REPLACE TABLE MEDICLAIM_DEMO_DB.SOURCE_DATA.MEDICLAIM_CUSTOMER_FEEDBACK (
 FEEDBACK_ID VARCHAR, CUSTOMER_ID VARCHAR, FEEDBACK_DATE DATE,
 CATEGORY VARCHAR, CUSTOMER_COMMENT VARCHAR, EXPECTED_SENTIMENT VARCHAR
);


-- Validation
SELECT COUNT(*) AS CLAIM_COUNT FROM MEDICLAIM_DEMO_DB.SOURCE_DATA.MEDICLAIM_CLAIMS;
SELECT COUNT(*) AS FEEDBACK_COUNT FROM MEDICLAIM_DEMO_DB.SOURCE_DATA.MEDICLAIM_CUSTOMER_FEEDBACK;
SELECT FRAUD_TYPE, COUNT(*) AS CLAIM_COUNT, SUM(CLAIM_AMOUNT) AS TOTAL_CLAIM_AMOUNT
FROM MEDICLAIM_DEMO_DB.SOURCE_DATA.MEDICLAIM_CLAIMS
GROUP BY FRAUD_TYPE ORDER BY FRAUD_TYPE;
SELECT EXPECTED_SENTIMENT, COUNT(*) AS FEEDBACK_COUNT
FROM MEDICLAIM_DEMO_DB.SOURCE_DATA.MEDICLAIM_CUSTOMER_FEEDBACK
GROUP BY EXPECTED_SENTIMENT ORDER BY EXPECTED_SENTIMENT;
